def P(text='',style=None,align=None,italic=False,bold=False,indent=True,space_before=0,size=None):
    p=doc.add_paragraph()
    p.paragraph_format.line_spacing_rule=WD_LINE_SPACING.DOUBLE
    p.paragraph_format.space_before=Pt(space_before)
    p.paragraph_format.space_after=Pt(0)
    if indent: p.paragraph_format.first_line_indent=Inches(0.5)
    if align: p.alignment=align
    r=p.add_run(text); r.italic=italic; r.bold=bold
    if size: r.font.size=Pt(size)
    return p

def RICH(parts, align=None, indent=True, space_before=0):
    p=doc.add_paragraph()
    p.paragraph_format.line_spacing_rule=WD_LINE_SPACING.DOUBLE
    p.paragraph_format.space_before=Pt(space_before)
    p.paragraph_format.space_after=Pt(0)
    if indent: p.paragraph_format.first_line_indent=Inches(0.5)
    if align: p.alignment=align
    for t,it in parts:
        r=p.add_run(t); r.italic=it
    return p

